using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class RegionalSceneryTests
{
 static WorldSession New()=>new(RegionalScenery.Create());
 static RegionalRequest Line(string id,FieldPoint a,FieldPoint b)=>new(new(id),ContractFixture.Officer,ContractFixture.Officer,RegionalAction.Move,a,b);
 [Fact] public void OldProfileAndNewProfileRemainSeparate(){var old=RegionalBattle.Create();var next=RegionalScenery.Create();Assert.NotEqual(old.Definitions.Version,next.Definitions.Version);Assert.Equal(RegionalBattle.Ruleset,old.Definitions.Ruleset);Assert.Equal(RegionalScenery.Ruleset,next.Definitions.Ruleset);Assert.Equal(0,RegionalGround.Height(new(5000,5000)));Assert.Equal(43000,RegionalScenery.Height(new(50000,70000)));ContractValidation.Validate(next);}
 [Fact] public void EveryTriangleInterpolatesTheSameAuthoritativeHeight(){foreach(var t in RegionalScenery.Surfaces()){foreach(var (a,b) in new[]{(2L,3L),(1L,1L)}){var p=new FieldPoint((t.A.Point.X*a+t.B.Point.X*b+t.C.Point.X)/(a+b+1),(t.A.Point.Y*a+t.B.Point.Y*b+t.C.Point.Y)/(a+b+1));decimal ax=t.A.Point.X,ay=t.A.Point.Y,bx=t.B.Point.X,by=t.B.Point.Y,cx=t.C.Point.X,cy=t.C.Point.Y;decimal det=(by-cy)*(ax-cx)+(cx-bx)*(ay-cy);decimal u=((by-cy)*(p.X-cx)+(cx-bx)*(p.Y-cy))/det;decimal v=((cy-ay)*(p.X-cx)+(ax-cx)*(p.Y-cy))/det;decimal height=u*t.A.HeightMm+v*t.B.HeightMm+(1-u-v)*t.C.HeightMm;Assert.InRange(Math.Abs(height-RegionalScenery.Height(p)),0,1);}}}
 [Fact] public void TrunksWallsAndBridgeRailsMatchBlockedFootprints(){Assert.NotEmpty(RegionalScenery.Obstacles);foreach(var o in RegionalScenery.Obstacles){var p=new FieldPoint((o.Min.X+o.Max.X)/2,(o.Min.Y+o.Max.Y)/2);Assert.False(RegionalGround.Walkable(p,true));}Assert.True(RegionalGround.Walkable(new(5000,55000),true));Assert.True(RegionalGround.Walkable(new(-27000,-25000),true));Assert.False(RegionalGround.Walkable(new(-35000,55000),true));}
 [Fact] public void BridgeCrossingAndForestRouteAvoidPhysicalObstacles(){foreach(var (from,to) in new[]{(new FieldPoint(5000,35000),new FieldPoint(5000,75000)),(new FieldPoint(5000,5000),new FieldPoint(25000,25000)),(new FieldPoint(-15000,-25000),new FieldPoint(-42000,-25000))}){var path=RegionalGround.Plan(from,to,0,scenery:true);Assert.NotEmpty(path);RegionalGround.ValidatePath(path,from,to,scenery:true);for(long t=0;t<=path[^1].EndAt;t++)Assert.True(RegionalGround.Walkable(RegionalGround.At(path,from,t),true));}}
 [Fact] public void RiverAndRidgeCliffRejectFormationGoal(){var s=New();var before=s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position).ToArray();var r=s.IssueRegional(Line("request:water",new(-35000,55000),new(-15000,55000)),s.Revision);Assert.Equal(ResultCode.Accepted,r.Code);Assert.Equal("blocked-hold",s.DiagnosticSnapshot().Region!.Commands[0].Result);Assert.Equal(before,s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position));Assert.Throws<InvalidDataException>(()=>RegionalGround.Plan(new(5000,5000),new(45000,65000),0,scenery:true));}
 [Theory][InlineData(7)][InlineData(55)][InlineData(150)] public void SceneryMovementAndGenerationRestoreStayIdentical(int at){var s=New();Assert.Equal(ResultCode.Accepted,s.IssueRegional(Line("request:scenery",new(25000,25000),new(65000,-25000)),s.Revision).Code);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands[0].Result);s.AdvanceTo(at);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"scenery-"+Guid.NewGuid().ToString("N")),RegionalScenery.Create().Definitions);store.Save(s,"stage",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("stage"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(500);host.Current.AdvanceTo(500);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Region),ContractJson.Write(host.Current.DiagnosticSnapshot().Region));Assert.All(s.DiagnosticSnapshot().Region!.Units,u=>Assert.True(RegionalGround.Walkable(u.Position,true)));}
 [Fact] public void TerrainDefinitionMismatchRejectsOldSavedWorld(){var old=RegionalBattle.Create();var path=Path.Combine(Path.GetTempPath(),"scenery-old-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(path,old.Definitions);store.Save(new(old),"stage",old.WorldId,new(0,1));var other=new GenerationSaveStore(path,RegionalScenery.Create().Definitions);Assert.Throws<ContractLoadException>(()=>other.Prepare("stage"));}
 [Fact] public void ThreeDetachmentsEnterTheCourtyardThroughTheGate(){var s=New();Assert.Equal(ResultCode.Accepted,s.IssueRegional(Line("request:castle",new(-42000,-32000),new(-30000,-32000)),s.Revision).Code);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands[0].Result);s.AdvanceTo(600);Assert.All(s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Officer),u=>Assert.Equal(u.Goal,u.Position));}
 [Fact] public void MovieSequenceActuallyMovesFromForestAcrossBridgeIntoFort(){var s=New();foreach(var (at,r) in new[]{(0L,Line("request:forest",new(25000,25000),new(65000,-25000))),(152L,Line("request:bridge",new(-15000,85000),new(5000,85000))),(390L,Line("request:courtyard",new(-42000,-32000),new(-30000,-32000)))}){s.AdvanceTo(at);Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands.Last().Result);}s.AdvanceTo(747);Assert.All(s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Officer),u=>Assert.Equal(u.Goal,u.Position));}
}
